#!/usr/bin/env python3
"""Writes the hedra command files of Plank Pass's simple models (their rows in art/assets.md are the brief):
terrain (the valley road's banks, the five gaps' floors and back walls, the anchor plates, the hill behind),
pines, plank, girder, puff, splash, dust, depot.

The world (glTF metres, Y up, +Z towards the camera; game.as holds the same numbers): one valley road along
+X at y 0 (y 1 after Step Gorge), cut by five gaps. The camera looks along -Z from the front, a little from
above, so faces towards -Z, the gap walls (facing +-X, seen edge-on) and the bottoms are never seen: they are
not modelled. Positions are written as hedra's (x, -z, y).
Run from this folder: python3 make_env.py; then `hedra model --text <m>.rmdl run <m>.txt` (build.sh)."""
import math
import random

COL = {  # Cretaceous-16, sRGB 0..1
    "k": "#313432", "s1": "#323e42", "s2": "#454b4b", "g1": "#3a5f3b", "r": "#7c4545", "w1": "#675239",
    "m": "#625055", "g2": "#516b43", "rk": "#796c64", "g3": "#718245", "w2": "#9e805c", "rl": "#998579",
    "pk": "#ac9086", "lg": "#a6a296", "kh": "#b4ab8f", "cr": "#bcb7a5"}


def rgb(h):
    h = COL[h].lstrip("#")
    return " ".join(f"{int(h[i:i + 2], 16) / 255:.3f}" for i in (0, 2, 4))


def mats(L, *pairs):
    for name, col in pairs:
        L.append(f"material new {name} --base-color {rgb(col)} --no-slot")


def H(x, y, z):
    return f"{x:.3f} {-z:.3f} {y:.3f}"


def box(L, name, x0, x1, y0, y1, z0, z1, mat, keep=None, top=None):
    """an axis-aligned box in glTF coordinates; keep: the faces kept ('top', 'front'); top: the top's material"""
    L.append(f"add mesh cube --name {name} --size 1 --location {H((x0 + x1) / 2, (y0 + y1) / 2, (z0 + z1) / 2)}")
    L.append(f"scale {x1 - x0:.3f} {z1 - z0:.3f} {y1 - y0:.3f}")
    L.append("apply --scale")
    L.append(f"material assign {mat}")
    if keep is not None:
        # hedra: top = +Z, front (towards the camera, glTF +Z) = -Y
        tests = []
        if "top" not in keep:
            tests.append("normal.z > 0.5")
        if "front" not in keep:
            tests.append("normal.y < -0.5")
        tests += ["normal.z < -0.5", "normal.y > 0.5", "abs(normal.x) > 0.5"]
        L += [f"active {name}", "mode edit", "select face where \"" + " || ".join(tests) + "\"", "delete face", "mode object"]
    if top:
        L += [f"active {name}", "mode edit", "select face where \"normal.z > 0.5\"", f"material assign {top}", "mode object"]


def write(name, L):
    L += ["select all", "shade flat", f"export {name}.glb"]
    open(f"{name}.txt", "w").write("\n".join(L) + "\n")


# ---------------------------------------------------------------- the world
BOTTOM = -6.5        # the banks' front faces reach down to here (below the frame)
FRONT = 1.2          # the banks' front face
ROAD = 0.8           # the road's half width
BACK = -3.0          # the gaps' back walls, where the hill starts
# gaps: centre, base y, left edge, right edge (relative), right bank's y (relative), floor (relative), water
GAPS = [
    (0.0, 0.0, -3, 3, 0, -3.0, True),      # MILL CREEK
    (18.0, 0.0, -4, 4, 0, -4.5, False),    # FERN GULLY
    (36.0, 0.0, -4, 4, 1, -4.5, False),    # STEP GORGE
    (56.0, 1.0, -6, 6, 0, -3.5, True),     # TWIN ROCK (a rock pillar in the middle)
    (78.0, 1.0, -6, 6, 0, -3.5, True),     # LONG WASH
]
ANCHORS = [
    [(-3, 0), (3, 0), (-3, -2), (3, -2)],
    [(-4, 0), (4, 0), (-4, -2), (4, -2)],
    [(-4, 0), (4, 1), (-4, -2), (4, -1)],
    [(-6, 0), (6, 0), (-6, -2), (6, -2), (-1, -2), (1, -2)],
    [(-6, 0), (6, 0), (-6, -3), (6, -3)],
]
START, END = -14.0, 100.0


def banks():
    out = []
    x, y = START, 0.0
    for (c, yb, l, r, yr, fl, wet) in GAPS:
        out.append((x, c + l, y))
        x, y = c + r, yb + yr
    out.append((x, END, y))
    return out


L = ["# The valley road: banks, the gaps' floors and back walls, anchor plates, the hill (generated by make_env.py).", "new"]
mats(L, ("Grass", "g2"), ("Dust", "rl"), ("Rock", "rk"), ("Wall", "m"), ("Water", "s2"), ("Foam", "cr"),
     ("Stone", "rl"), ("Plate", "s2"), ("Hill", "g3"))
for k, (x0, x1, y) in enumerate(banks()):
    # the front: a grass verge on a rock face down to the bottom; the road; the grass behind it
    box(L, f"Front{k}", x0, x1, BOTTOM, y, ROAD, FRONT, "Rock", keep=("top", "front"), top="Grass")
    box(L, f"Road{k}", x0, x1, y - 0.2, y, -ROAD, ROAD, "Dust", keep=("top",))
    box(L, f"Verge{k}", x0, x1, y - 0.2, y, BACK, -ROAD, "Grass", keep=("top",))
    # a darker stratum band across the front face, 1.2 m below the verge
    box(L, f"Band{k}", x0, x1, y - 2.0, y - 1.3, FRONT, FRONT + 0.06, "Wall", keep=("front",))
for g, (c, yb, l, r, yr, fl, wet) in enumerate(GAPS):
    x0, x1 = c + l, c + r
    yl, yrr = yb, yb + yr
    floor = yb + fl
    # the back wall: rock from the floor up to the road on each side
    box(L, f"Back{g}", x0, x1, floor - 0.3, max(yl, yrr), BACK - 0.2, BACK, "Wall", keep=("front",))
    if wet:
        box(L, f"Water{g}", x0, x1, BOTTOM, floor, BACK, FRONT, "Water", keep=("top", "front"))
    else:
        box(L, f"Floor{g}", x0, x1, BOTTOM, floor, BACK, FRONT, "Stone", keep=("top", "front"))
    # anchor plates: steel blocks where the beams may start (bank edges, the cliff faces, the rock)
    for (ax, ay) in ANCHORS[g]:
        X, Y = c + ax, yb + ay
        box(L, f"Plate{g}_{ax}_{ay}", X - 0.22, X + 0.22, Y - 0.22, Y + 0.22, -0.7, 0.7, "Plate", keep=("top", "front"))
# Twin Rock's pillar, from the water up to its two anchors
c, yb = 56.0, 1.0
box(L, "Pillar", c - 1.3, c + 1.3, yb - 3.7, yb - 2.0, -1.6, 0.9, "Rock", keep=("top", "front"), top="Stone")
box(L, "PillarCap", c - 0.8, c + 0.8, yb - 2.0, yb - 1.75, -1.0, 0.5, "Stone", keep=("top", "front"))
# the hill behind the road: a slope from the gaps' back walls up to a ridge, step at Step Gorge
for k, (x0, x1, y) in enumerate(((START, 36.0, 0.0), (36.0, END, 1.0))):
    run, rise = 3.5, 0.9
    ang = math.degrees(math.atan2(rise, run))
    ln = math.hypot(run, rise)
    L.append(f"add mesh plane --name Hill{k} --size 1 --location {H((x0 + x1) / 2, y + rise / 2, BACK - run / 2)}")
    L.append(f"scale {x1 - x0:.3f} {ln:.3f} 1")
    L.append("apply --scale")
    L.append(f"set rotation {ang:.2f} 0 0")
    L.append("apply --rotation")
    L.append("material assign Hill")
write("terrain", L)

# ---------------------------------------------------------------- pines on the hill (one model, many instances)
L = ["# A pine: a trunk and three stacked six-sided cones (generated by make_env.py), origin at its foot.", "new"]
mats(L, ("Needles", "g1"), ("Trunk", "w1"))
L += ["add mesh cylinder --name Trunk --vertices 6 --radius 0.13 --depth 0.5 --location 0 0 0.25", "material assign Trunk"]
for k, (z, r, d) in enumerate(((0.75, 0.75, 1.0), (1.35, 0.58, 0.9), (1.9, 0.38, 0.8))):
    L += [f"add mesh cone --name Tier{k} --vertices 6 --radius1 {r} --radius2 0.02 --depth {d} --location 0 0 {z}", "material assign Needles"]
write("pine", L)

# ---------------------------------------------------------------- a boulder (dry floors, the banks)
L = ["# A boulder (generated by make_env.py).", "new"]
mats(L, ("Boulder", "rl"))
L += ["add mesh ico-sphere --name Boulder --subdivisions 1 --radius 0.5 --location 0 0 0.3", "scale 1.2 0.9 0.75", "apply --scale",
      "material assign Boulder"]
write("boulder", L)

# ---------------------------------------------------------------- the beams: baked at the longest (3.2 m), only shortened
MAXLEN = 3.2
L = ["# A deck plank (generated by make_env.py): 3.2 m along +X from the origin, 0.22 thick, 1.2 wide (the road).", "new"]
mats(L, ("Plank", "w2"), ("PlankEdge", "w1"))
L += [f"add mesh cube --name Plank --size 1 --location {H(MAXLEN / 2, 0, 0)}", f"scale {MAXLEN} 1.2 0.22", "apply --scale",
      "material assign Plank", "active Plank", "mode edit", "select face where \"normal.y < -0.5 || abs(normal.x) > 0.5\"",
      "material assign PlankEdge", "select face where \"normal.y > 0.5 || normal.z < -0.5\"", "delete face", "mode object"]
write("plank", L)
L = ["# A steel girder (generated by make_env.py): 3.2 m along +X from the origin, 0.2 x 0.2, on the far side (z -0.55).", "new"]
mats(L, ("Girder", "s2"))
L += [f"add mesh cube --name Girder --size 1 --location {H(MAXLEN / 2, 0, -0.55)}", f"scale {MAXLEN} 0.2 0.2", "apply --scale",
      "material assign Girder"]
write("girder", L)

# ---------------------------------------------------------------- effects
L = ["# A steam puff (generated by make_env.py).", "new"]
mats(L, ("Steam", "cr"))
L += ["add mesh ico-sphere --name Puff --subdivisions 1 --radius 0.2 --location 0 0 0", "material assign Steam"]
write("puff", L)

L = ["# A splash (generated by make_env.py), origin at the water.", "new"]
mats(L, ("Spray", "cr"))
for k in range(6):
    a = k * math.pi / 3
    L += [f"add mesh ico-sphere --name Drop{k} --subdivisions 1 --radius 0.2 --location {0.6 * math.cos(a):.3f} {0.4 * math.sin(a):.3f} {0.35 + 0.2 * (k % 2):.2f}",
          "material assign Spray"]
L += ["add mesh cone --name Column --vertices 6 --radius1 0.5 --radius2 0.15 --depth 1.1 --location 0 0 0.55", "material assign Spray"]
write("splash", L)

L = ["# A dust cloud (generated by make_env.py), origin on the ground.", "new"]
mats(L, ("DustCloud", "lg"))
for k in range(7):
    a = k * 2 * math.pi / 7
    L += [f"add mesh ico-sphere --name Cloud{k} --subdivisions 1 --radius {0.32 + 0.08 * (k % 3):.2f} --location {0.75 * math.cos(a):.3f} {0.3 * math.sin(a):.3f} {0.3 + 0.15 * (k % 2):.2f}",
          "material assign DustCloud"]
write("dust", L)

# ---------------------------------------------------------------- the depot at the end of the road
L = ["# The road's end: a little depot shed with a red roof (generated by make_env.py), origin at its foot.", "new"]
mats(L, ("Planks", "w2"), ("Roof", "r"), ("Door", "w1"))
L += [f"add mesh cube --name Shed --size 1 --location {H(0, 1.0, 0)}", "scale 3.0 2.4 2.0", "apply --scale", "material assign Planks",
      f"add mesh cube --name Door --size 1 --location {H(-0.4, 0.8, 1.22)}", "scale 0.9 0.06 1.6", "apply --scale", "material assign Door",
      f"add mesh cone --name Roof --vertices 4 --radius1 2.4 --radius2 0.05 --depth 1.3 --location {H(0, 2.65, 0)}",
      "set rotation 0 0 45", "apply --rotation", "scale 1.0 0.75 1", "apply --scale", "material assign Roof"]
write("depot", L)

# the pines' and boulders' places (the bake file lists them; printed for scene.bake.json)
if __name__ == "__main__":
    rnd = random.Random(7)
    pines = []
    x = START + 1.0
    while x < END - 1:
        yb = 0.0 if x < 36 else 1.0
        d = rnd.uniform(0.5, 3.2)                    # up the hill from its foot
        pines.append([round(x, 2), round(yb + d * 0.9 / 3.5 - 0.05, 2), round(BACK - 0.5 - d, 2), rnd.randint(0, 359), round(rnd.uniform(0.75, 1.15), 2)])
        x += rnd.uniform(2.2, 4.8)
    import json
    json.dump({"pines": pines}, open("places.json", "w"))
    print(len(pines), "pines")
